from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            # remove expired entries lazily for this key
            if key in cache:
                v, wt = cache[key]
                if t >= wt + ttl:
                    # expired, treat as absent
                    del cache[key]

            if key in cache:
                # update existing, move to end (most recently used)
                cache[key] = (value, t)
                cache.move_to_end(key)
            else:
                # need to add new entry, check capacity
                # first remove expired entries to make room if needed (optional cleanup)
                if len(cache) >= capacity:
                    # evict LRU (first item), but need to check if it's expired first? 
                    # Actually eviction happens if key is absent and cache already holds capacity entries
                    # We should evict oldest (first in OrderedDict)
                    cache.popitem(last=False)
                cache[key] = (value, t)
                cache.move_to_end(key)

        elif op[0] == 'get':
            _, t, key = op
            if key in cache:
                v, wt = cache[key]
                if t >= wt + ttl:
                    del cache[key]
                    results.append(-1)
                else:
                    results.append(v)
                    cache.move_to_end(key)
            else:
                results.append(-1)

    return results

